# ============================================================
# V62 Backend result collector
# ============================================================
# This list is populated by both v34 and v42 engines when they finish
# building panel_calc_entries. It is cleared at the start of each
# process_image_for_backend() call.
_BACKEND_RESULT_PANELS: List[Dict[str, Any]] = []


def _normalize_polygon_for_backend(poly):
    if poly is None:
        return []
    try:
        if hasattr(poly, "tolist"):
            pts = poly.tolist()
        else:
            pts = list(poly)
        res = []
        for pt in pts:
            if hasattr(pt, "tolist"):
                pt_list = pt.tolist()
            else:
                pt_list = list(pt)
            if len(pt_list) >= 2:
                res.append([float(pt_list[0]), float(pt_list[1])])
        return res
    except Exception:
        return []


def _polygon_area_backend(poly):
    if not poly or len(poly) < 3:
        return 0.0
    try:
        return float(cv2.contourArea(np.array(poly, dtype=np.float32)))
    except Exception:
        return 0.0


def _backend_inset_quad_polygon(poly, margin_px):
    poly_f = np.array(poly, dtype=np.float32)
    if poly_f.shape != (4, 2):
        return poly_f, "invalid_shape", False
    centroid = np.mean(poly_f, axis=0)
    angles = np.arctan2(poly_f[:, 1] - centroid[1], poly_f[:, 0] - centroid[0])
    sorted_indices = np.argsort(angles)
    q = poly_f[sorted_indices]
    lines = []
    has_zero_edge = False
    for i in range(4):
        p_i = q[i]
        p_j = q[(i + 1) % 4]
        dx = p_j[0] - p_i[0]
        dy = p_j[1] - p_i[1]
        edge_len = math.sqrt(dx*dx + dy*dy)
        if edge_len < 1e-6:
            has_zero_edge = True
            break
        nx = -dy / edge_len
        ny = dx / edge_len
        midpoint = (p_i + p_j) / 2.0
        to_centroid_x = centroid[0] - midpoint[0]
        to_centroid_y = centroid[1] - midpoint[1]
        dot_val = nx * to_centroid_x + ny * to_centroid_y
        if dot_val < 0:
            nx = -nx
            ny = -ny
        d = nx * p_i[0] + ny * p_i[1] + margin_px
        lines.append((nx, ny, d))
    if has_zero_edge:
        return poly_f, "zero_edge", False
    pts_new = []
    for i in range(4):
        nx1, ny1, d1 = lines[i]
        nx2, ny2, d2 = lines[(i + 1) % 4]
        det = nx1 * ny2 - ny1 * nx2
        if abs(det) < 1e-6:
            return poly_f, "parallel_edges", False
        px = (d1 * ny2 - ny1 * d2) / det
        py = (nx1 * d2 - d1 * nx2) / det
        pts_new.append([px, py])
    return np.array(pts_new, dtype=np.float32), "geometric_inset", True


def _backend_append_panel(
    outer_polygon,
    inner_polygon=None,
    source="line_snap",
    engine="unknown",
    valid=True,
    filter_reason="",
    outer_area=None,
    inner_area=None,
):
    global _BACKEND_RESULT_PANELS

    outer = _normalize_polygon_for_backend(outer_polygon)
    inner = _normalize_polygon_for_backend(inner_polygon) if inner_polygon is not None else []

    if not outer or len(outer) < 3:
        return

    if not inner or len(inner) < 3:
        try:
            inner_poly, _, inset_valid = _backend_inset_quad_polygon(np.array(outer, dtype=np.float32), INNER_PANEL_MARGIN_PX)
            if inset_valid:
                inner = _normalize_polygon_for_backend(inner_poly)
            else:
                inner = outer
        except Exception:
            inner = outer

    if outer_area is None:
        outer_area = _polygon_area_backend(outer)
    else:
        outer_area = float(outer_area)

    if inner_area is None:
        inner_area = _polygon_area_backend(inner)
    else:
        inner_area = float(inner_area)

    _BACKEND_RESULT_PANELS.append({
        "outer_polygon": outer,
        "inner_polygon": inner,
        "calc_polygon": inner,
        "outer_area": outer_area,
        "inner_area": inner_area,
        "valid": bool(valid),
        "filter_reason": filter_reason or "",
        "source": source,
        "engine": engine,
    })

